-- Forward-only M3-07 claim repair: generated component facts retain the
-- field-level canonical CPE decision alongside PURL and hashes.

create or replace function public.claim_sbom_composite_generation(p_organization_id uuid,p_worker_id uuid,p_lease_seconds integer)
returns table(outcome text,work jsonb) language plpgsql security definer set search_path=public,pg_temp as $$
declare v_review public.sbom_composite_reviews%rowtype; v_components jsonb; v_dependencies jsonb;
begin
  if p_worker_id is null or p_lease_seconds not between 15 and 900 then return query select 'invalid_request'::text,null::jsonb; return; end if;
  select * into v_review from public.sbom_composite_reviews r where r.organization_id=p_organization_id and r.status='processing' and (r.lease_expires_at is null or r.lease_expires_at<=now()) and (r.generated_source_id is not null or r.attempt_count<5) order by r.created_at,r.id for update skip locked limit 1;
  if not found then return query select 'empty'::text,null::jsonb; return; end if;
  update public.sbom_composite_reviews r set lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),attempt_count=r.attempt_count+case when r.generated_source_id is null then 1 else 0 end where r.organization_id=p_organization_id and r.id=v_review.id returning * into v_review;
  perform public.sync_sbom_composite_selected_provenance(p_organization_id,v_review.id);
  with candidates as (
    select i.source_id,i.document_id,c.id component_id,c.document_local_ref,c.source_offset,c.normalized_name,c.normalized_version,c.canonical_purl,c.cpe,c.hashes,public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) identity_key,row_number() over(partition by public.sbom_composite_identity_key(c.canonical_purl,c.cpe,c.hashes,i.document_id,c.document_local_ref) order by i.source_id,c.source_offset,c.id) rn from public.sbom_composite_review_inputs i join public.sbom_components c on c.organization_id=i.organization_id and c.document_id=i.document_id where i.organization_id=p_organization_id and i.review_id=v_review.id
  ), decisions as (
    select c.identity_key,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='incompatible_version' and c.selected_source_component_id is not null))[1] vc,(array_agg(c.selected_source_component_id order by c.selected_source_component_id) filter(where c.conflict_type='field_conflict' and c.selected_source_component_id is not null))[1] fc,bool_or(c.selected_source_component_id is null and c.resolution_reason is not null) excluded,bool_or(c.selected_source_component_id is null and c.resolution_reason is null) unresolved,count(*) conflict_count from public.sbom_composite_conflicts c where c.organization_id=p_organization_id and c.review_id=v_review.id group by c.identity_key
  ), selected as (
    select c.*,case when c.identity_key like 'unresolved:%' then 'component:'||c.document_id::text||':'||c.document_local_ref else 'component:'||encode(extensions.digest(c.identity_key||'@'||coalesce(c.normalized_version,''),'sha256'),'hex') end composite_ref from candidates c left join decisions d on d.identity_key=c.identity_key where not coalesce(d.excluded,false) and not coalesce(d.unresolved,false) and ((d.vc is not null and c.component_id=d.vc) or (d.vc is null and d.fc is not null and c.component_id=d.fc) or (d.conflict_count is null and c.rn=1) or c.identity_key like 'unresolved:%')
  )
  select coalesce(jsonb_agg(jsonb_build_object('componentRef',s.composite_ref,'name',coalesce((select c.normalized_name from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='name' and x.selected_source_component_id is not null order by x.id limit 1),s.normalized_name),'version',s.normalized_version,'canonicalPurl',coalesce((select c.canonical_purl from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='canonicalPurl' and x.selected_source_component_id is not null order by x.id limit 1),s.canonical_purl),'canonicalCpe',coalesce((select c.cpe from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='canonicalCpe' and x.selected_source_component_id is not null order by x.id limit 1),s.cpe),'hashes',coalesce((select c.hashes from public.sbom_composite_conflicts x join candidates c on c.component_id=x.selected_source_component_id where x.organization_id=p_organization_id and x.review_id=v_review.id and x.identity_key=s.identity_key and x.conflict_type='field_conflict' and x.field_name='hashes' and x.selected_source_component_id is not null order by x.id limit 1),s.hashes),'sourceComponentId',s.component_id,'sourceId',s.source_id,'documentId',s.document_id) order by s.composite_ref,s.source_id,s.source_offset,s.component_id),'[]'::jsonb) into v_components from selected s;
  select coalesce(jsonb_agg(jsonb_build_object('fromRef',d.composite_parent_ref,'toRef',d.composite_child_ref) order by d.composite_parent_ref,d.composite_child_ref),'[]'::jsonb) into v_dependencies from (select distinct composite_parent_ref,composite_child_ref from public.sbom_composite_dependency_provenance d where d.organization_id=p_organization_id and d.review_id=v_review.id) d;
  return query select 'claimed'::text,jsonb_build_object('reviewId',v_review.id,'actorId',v_review.created_by,'productId',v_review.product_id,'releaseId',v_review.release_id,'mergeRulesVersion',v_review.merge_rules_version,'generatedSourceId',v_review.generated_source_id,'components',v_components,'dependencies',v_dependencies);
end;
$$;

revoke all on function public.claim_sbom_composite_generation(uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.claim_sbom_composite_generation(uuid,uuid,integer) to service_role;
